function longestPalindrome(s) {
  const n = s.length;
  // pal[i][j]: is s[i..j] a palindrome? Its ends must match and its inside must be one.
  const pal = Array.from({ length: n }, () => new Array(n).fill(false));
  let bestStart = 0, bestLen = 1;
  for (let i = n - 1; i >= 0; i--) {         // i goes down so row i + 1 is ready
    for (let j = i; j < n; j++) {
      pal[i][j] = s[i] === s[j] && (j - i < 3 || pal[i + 1][j - 1]);
      if (pal[i][j] && j - i + 1 > bestLen) {
        bestStart = i;
        bestLen = j - i + 1;
      }
    }
  }
  return s.slice(bestStart, bestStart + bestLen);
}

