        expand(s, center, center + 1);           // even length: the gap after it
    }
    return s.substring(bestStart, bestStart + bestLen);
}

void expand(String s, int left, int right) {     // grow outwards while the ends match
    while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
        left--;
        right++;
    }
    // The loop went one step too far on each side: the palindrome is s[left+1..right-1].
    if (right - left - 1 > bestLen) {
        bestStart = left + 1;
        bestLen = right - left - 1;
    }
}

